-- ============================================================================
-- DB Internals - Seed Database
-- ============================================================================
-- E-commerce sample database with 5 related tables (100x scale)
--
-- Schema Overview:
--   users (1) ──────< (N) orders (1) ──────< (N) order_items (N) >────── (1) products
--                                                                                  ^
--                                                                                  |
--                                                                  categories (1) ─┘
--
-- Note: Foreign key constraints are NOT enforced by the storage layer.
--       Referential integrity is maintained by the data values only.
-- ============================================================================

-- ============================================================================
-- Table: users
-- Description: Customer accounts (1000 records)
-- ============================================================================
CREATE TABLE users (
    id INT,
    username VARCHAR(64),
    email VARCHAR(255),
    created_at DATETIME,
    is_active BOOLEAN
)


-- ============================================================================
-- Table: categories
-- Description: Product categories (500 records)
-- Relationship: 1 category → N products
-- ============================================================================
CREATE TABLE categories (
    id INT,
    name VARCHAR(128),
    description VARCHAR(512)?
)


-- ============================================================================
-- Table: products
-- Description: Product catalog (2000 records)
-- Relationships: N products → 1 category, 1 product → N order_items
-- Note: price values are integers (parser limitation: no float literals)
--       The seeddb tool will convert them to DOUBLE (e.g., 2999 → 29.99)
-- ============================================================================
CREATE TABLE products (
    id INT,
    name VARCHAR(255),
    category_id INT,
    price DOUBLE,
    stock INT,
    created_at DATETIME
)


-- ============================================================================
-- Table: orders
-- Description: Customer orders (1500 records)
-- Relationships: N orders → 1 user, 1 order → N order_items
-- Note: total_amount values are integers (parser limitation: no float literals)
--       The seeddb tool will convert them to DOUBLE (e.g., 13598 → 135.98)
-- ============================================================================
CREATE TABLE orders (
    id INT,
    user_id INT,
    order_date DATETIME,
    total_amount DOUBLE,
    status VARCHAR(32)
)


-- ============================================================================
-- Table: order_items
-- Description: Line items in orders (3000 records)
-- Relationships: N order_items → 1 order, N order_items → 1 product
-- Note: unit_price values are integers (parser limitation: no float literals)
--       The seeddb tool will convert them to DOUBLE (e.g., 2999 → 29.99)
-- ============================================================================
CREATE TABLE order_items (
    id INT,
    order_id INT,
    product_id INT,
    quantity INT,
    unit_price DOUBLE
)

